"use strict";(globalThis.webpackChunk_effectstream_docs=globalThis.webpackChunk_effectstream_docs||[]).push([[4216],{64752(e,n,t){t.r(n),t.d(n,{assets:()=>c,contentTitle:()=>a,default:()=>h,frontMatter:()=>s,metadata:()=>o,toc:()=>d});const o=JSON.parse('{"id":"home/paima-standards/prc2","title":"PRC-2 \u2014 Paima Hololocker Interface","description":"Use case","source":"@site/docs/home/400-paima-standards/prc2.md","sourceDirName":"home/400-paima-standards","slug":"/home/paima-standards/prc2","permalink":"/docs/home/paima-standards/prc2","draft":false,"unlisted":false,"editUrl":"https://github.com/PaimaStudios/paima-engine-docs/tree/main/docs/home/400-paima-standards/prc2.md","tags":[],"version":"current","frontMatter":{},"sidebar":"tutorialSidebar","previous":{"title":"PRC-1 \u2014 Paima Achievement Interface","permalink":"/docs/home/paima-standards/prc1"},"next":{"title":"PRC-3 \u2014 Paima Inverse Projection Interface (ERC-721)","permalink":"/docs/home/paima-standards/prc3"}}');var r=t(74848),i=t(28453);const s={},a="PRC-2 \u2014 Paima Hololocker Interface",c={},d=[{value:"Use case",id:"use-case",level:2},{value:"Summary",id:"summary",level:2},{value:"Specification",id:"specification",level:2},{value:"Standard user flow",id:"standard-user-flow",level:3},{value:"Rationale",id:"rationale",level:2},{value:"Why &quot;Unlocking&quot; + <code>lockTime</code>?",id:"why-unlocking--locktime",level:3},{value:"Consistent contract address",id:"consistent-contract-address",level:3},{value:"Why not mint a &quot;receipt NFT&quot; on lock?",id:"why-not-mint-a-receipt-nft-on-lock",level:3},{value:"Why ERC-721 only?",id:"why-erc-721-only",level:3},{value:"Reference implementation",id:"reference-implementation",level:2},{value:"Security considerations",id:"security-considerations",level:2},{value:"Integration with EffectStream",id:"integration-with-effectstream",level:2}];function l(e){const n={a:"a",blockquote:"blockquote",code:"code",em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",hr:"hr",li:"li",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,i.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.header,{children:(0,r.jsx)(n.h1,{id:"prc-2--paima-hololocker-interface",children:"PRC-2 \u2014 Paima Hololocker Interface"})}),"\n",(0,r.jsx)(n.h2,{id:"use-case",children:"Use case"}),"\n",(0,r.jsxs)(n.p,{children:["A player owns a rare CryptoPunk on Ethereum mainnet and wants to use it as their in-game avatar in a Paima-powered game running on a different chain. They call ",(0,r.jsx)(n.code,{children:"lock()"})," on the Hololocker contract: the Punk stays in their control (held in a contract they can withdraw from at any time), and the game starts treating them as the avatar owner immediately. When they're done playing, they call ",(0,r.jsx)(n.code,{children:"requestUnlock()"}),", wait the configured cooldown (long enough to be safe against L1 reorgs), and ",(0,r.jsx)(n.code,{children:"withdraw()"}),". The Punk is back in their wallet \u2014 they never had to bridge it, never trusted a custodian, and never owned two copies of the same NFT at once."]}),"\n",(0,r.jsx)(n.h2,{id:"summary",children:"Summary"}),"\n",(0,r.jsxs)(n.p,{children:["Games are data- and computation-heavy and typically run on sidechains, L2s, or appchains, while popular NFT collections live on a different L1. PRC-2 lets users ",(0,r.jsx)(n.strong,{children:"project"})," an NFT they hold on the L1 directly into the game \u2014 no bridging, no wrapped tokens, no separate canonical copy. The user keeps unambiguous ownership of the L1 asset and can withdraw it at any time after a time-locked release."]}),"\n",(0,r.jsx)(n.p,{children:"The interface supports projecting one or many NFTs in a single call to save gas."}),"\n",(0,r.jsx)(n.h2,{id:"specification",children:"Specification"}),"\n",(0,r.jsxs)(n.p,{children:["Every PRC-2 compliant contract MUST implement ",(0,r.jsx)(n.code,{children:"HololockerInterface"}),":"]}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-solidity",children:"interface HololockerInterface is IERC721Receiver {\n    /// Per-NFT state stored by the locker.\n    struct LockInfo {\n        uint256 unlockTime;  // Withdrawable timestamp; 0 means unlock not yet requested\n        address owner;       // Rightful owner of the NFT\n        address operator;    // Account that initiated the lock\n    }\n\n    event Lock(address indexed token, address indexed owner, uint256 tokenId, address operator);\n    event Unlock(address indexed token, address indexed owner, uint256 tokenId, address operator, uint256 unlockTime);\n    event Withdraw(address indexed token, address indexed owner, uint256 tokenId, address operator);\n    event LockTimeUpdate(uint256 newValue);\n\n    /// Returns the LockInfo for a `<token, tokenId>` pair.\n    function getLockInfo(address token, uint256 tokenId) external view returns (LockInfo memory);\n\n    /// Initiates a lock for one or more NFTs. Stores `{owner, operator: msg.sender, unlockTime: 0}`\n    /// for each pair, emits `Lock`, and transfers each NFT to this contract.\n    /// Reverts if the two arrays have different lengths.\n    function lock(address[] memory tokens, uint256[] memory tokenIds, address owner) external;\n\n    /// Begins the unlock cooldown by setting `unlockTime = block.timestamp + lockTime` and emitting `Unlock`.\n    /// Reverts if msg.sender is neither owner nor operator for any pair, or if an unlock is already in progress.\n    function requestUnlock(address[] memory tokens, uint256[] memory tokenIds) external;\n\n    /// Withdraws each NFT to its rightful owner, provided `unlockTime` has elapsed.\n    /// Reverts if any pair has `unlockTime == 0` (no unlock requested) or `unlockTime > block.timestamp` (cooldown still active).\n    function withdraw(address[] memory tokens, uint256[] memory tokenIds) external;\n\n    /// The cooldown added to `block.timestamp` when an unlock is requested.\n    function getLockTime() external view returns (uint256);\n\n    /// Governance hook. The new value SHOULD be sanity-bounded; emits `LockTimeUpdate`.\n    function setLockTime(uint256 newLockTime) external;\n}\n"})}),"\n",(0,r.jsxs)(n.p,{children:["A Hololocker also implements ",(0,r.jsx)(n.code,{children:"IERC721Receiver"}),", so that NFTs can be locked by calling ",(0,r.jsx)(n.code,{children:"IERC721.safeTransferFrom(..., locker, ...)"}),". When called this way, the implementation MUST initialise the same ",(0,r.jsx)(n.code,{children:"LockInfo"})," it would have created via ",(0,r.jsx)(n.code,{children:"lock()"})," and emit the ",(0,r.jsx)(n.code,{children:"Lock"})," event."]}),"\n",(0,r.jsxs)(n.blockquote,{children:["\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Safety note."})," Always use ",(0,r.jsx)(n.code,{children:"safeTransferFrom"})," when sending an NFT to the locker. Plain ",(0,r.jsx)(n.code,{children:"transferFrom"})," skips ",(0,r.jsx)(n.code,{children:"onERC721Received"}),", and the locker has no way to record the previous owner \u2014 the NFT gets stuck in the contract."]}),"\n"]}),"\n",(0,r.jsx)(n.h3,{id:"standard-user-flow",children:"Standard user flow"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"Lock  \u2192  Request Unlock  \u2192  \u23f3 lockTime elapses  \u2192  Withdraw\n"})}),"\n",(0,r.jsxs)(n.p,{children:["The cooldown (",(0,r.jsx)(n.code,{children:"lockTime"}),") is what makes simultaneous double-use impossible. It should reflect the L1's finality budget \u2014 long enough that the in-game world can rely on a locked NFT being locked when it acts on it."]}),"\n",(0,r.jsx)(n.h2,{id:"rationale",children:"Rationale"}),"\n",(0,r.jsx)(n.p,{children:'The Hololocker is essentially an NFT-staking contract with an "Unlocking" state. Earlier proposals (e.g. EIP-4987) did not reach finalisation, so PRC-2 codifies the lightest-weight interface that does the job and is sufficient for in-game use.'}),"\n",(0,r.jsxs)(n.h3,{id:"why-unlocking--locktime",children:['Why "Unlocking" + ',(0,r.jsx)(n.code,{children:"lockTime"}),"?"]}),"\n",(0,r.jsxs)(n.p,{children:["Without a delay between ",(0,r.jsx)(n.em,{children:"requesting"})," an unlock and ",(0,r.jsx)(n.em,{children:"receiving"})," the NFT, the same asset could be used in two places at once \u2014 the game holds it, the L1 transfer finishes, and the new owner uses it too. A bounded cooldown forces a single source of truth."]}),"\n",(0,r.jsx)(n.h3,{id:"consistent-contract-address",children:"Consistent contract address"}),"\n",(0,r.jsxs)(n.p,{children:["To give users a predictable experience, the Hololocker SHOULD be deployed to the same address on every EVM chain that hosts it. The reference implementation pins ",(0,r.jsx)(n.code,{children:"bytes32(uint256(1))"})," as the salt in its Foundry script, deploying to ",(0,r.jsx)(n.code,{children:"0x963ba25745aEE135EdCFC2d992D5A939d42738B6"}),"."]}),"\n",(0,r.jsx)(n.h3,{id:"why-not-mint-a-receipt-nft-on-lock",children:'Why not mint a "receipt NFT" on lock?'}),"\n",(0,r.jsxs)(n.p,{children:["A receipt token would help UX \u2014 users could see the asset in their wallet \u2014 but it nearly doubles ",(0,r.jsx)(n.code,{children:"lock"}),"'s gas cost (85 k \u2192 161 k) and increases ",(0,r.jsx)(n.code,{children:"withdraw"})," cost by ~60 % (7.5 k \u2192 12.1 k). PRC-2 deliberately doesn't include one."]}),"\n",(0,r.jsx)(n.h3,{id:"why-erc-721-only",children:"Why ERC-721 only?"}),"\n",(0,r.jsx)(n.p,{children:"Other standards (ERC-20, ERC-1155) can be supported by analogous interfaces with the data model adjusted to amounts rather than ids. PRC-2 stays scoped to ERC-721 to keep the interface small."}),"\n",(0,r.jsx)(n.h2,{id:"reference-implementation",children:"Reference implementation"}),"\n",(0,r.jsx)(n.p,{children:(0,r.jsx)(n.a,{href:"https://github.com/dcSpark/projected-nft-whirlpool/blob/8b0d0367139eb9a43be94edff34a656258e25793/evm/src/Hololocker.sol",children:(0,r.jsx)(n.code,{children:"projected-nft-whirlpool/evm/src/Hololocker.sol"})})}),"\n",(0,r.jsx)(n.h2,{id:"security-considerations",children:"Security considerations"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["The locker MUST be entered via ",(0,r.jsx)(n.code,{children:"safeTransferFrom"}),". ",(0,r.jsx)(n.code,{children:"transferFrom"})," will permanently strand the NFT."]}),"\n",(0,r.jsxs)(n.li,{children:["The ",(0,r.jsx)(n.code,{children:"lockTime"})," setter MUST be access-controlled and SHOULD have an upper-bound check to prevent griefing."]}),"\n",(0,r.jsx)(n.li,{children:'The cooldown is the only mechanism preventing "use in two places at once" \u2014 it MUST be at least the L1\'s finality window for the deployed chain.'}),"\n"]}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"integration-with-effectstream",children:"Integration with EffectStream"}),"\n",(0,r.jsxs)(n.p,{children:["The Hololocker pattern is what EffectStream's ",(0,r.jsxs)(n.strong,{children:[(0,r.jsx)(n.code,{children:"CardanoProjectedNFT"})," primitive"]})," consumes for Cardano-side projections. The same shape applies to EVM-side Hololockers using the on-chain interface specified above."]}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Primitive"}),": parses Hololocker ",(0,r.jsx)(n.code,{children:"State"})," datums from the indexer stream and materialises a queryable PostgreSQL view of every projected NFT (",(0,r.jsx)(n.code,{children:"Lock"}),", ",(0,r.jsx)(n.code,{children:"Unlocking"}),", ",(0,r.jsx)(n.code,{children:"Claim"})," states + nullifier tracking). See the ",(0,r.jsx)(n.a,{href:"/docs/home/chains/cardano#primitives",children:"Cardano Primitives reference"}),"."]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Runnable template"}),": ",(0,r.jsx)(n.a,{href:"https://github.com/effectstream/effectstream/tree/v-next-bun-start/templates/projected-nft-preorder",children:(0,r.jsx)(n.code,{children:"templates/projected-nft-preorder"})})," is a complete devnet + indexer + sync node + React frontend that exercises the full Lock \u2192 Unlock \u2192 Claim lifecycle."]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Walkthrough"}),": the ",(0,r.jsx)(n.a,{href:"/docs/blog/projected-nfts",children:"Projected NFTs blog post"})," walks through the Aiken Cardano contract, the EffectStream primitive, and the dApp end-to-end."]}),"\n"]}),"\n",(0,r.jsxs)(n.p,{children:["For new EVM Hololocker deployments the ",(0,r.jsx)(n.a,{href:"https://github.com/dcSpark/projected-nft-whirlpool",children:(0,r.jsx)(n.code,{children:"dcSpark/projected-nft-whirlpool"})})," repository hosts the reference Solidity contract, the deployment script, and the dApp UI."]})]})}function h(e={}){const{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(l,{...e})}):l(e)}},28453(e,n,t){t.d(n,{R:()=>s,x:()=>a});var o=t(96540);const r={},i=o.createContext(r);function s(e){const n=o.useContext(i);return o.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function a(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:s(e.components),o.createElement(i.Provider,{value:n},e.children)}}}]);